import{_ as i,a0 as s,w as p,s as d,ao as r,I as n,x as e,a1 as l,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"全球化思考:怎樣克服交流中的文化差異 | LCTT x X-CMD","titleTemplate":false,"description":"全球化思考:怎樣克服交流中的文化差異 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"全球化思考:怎樣克服交流中的文化差異 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"全球化思考:怎樣克服交流中的文化差異 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20181018 Think global- How to overcome cultural communication challenges","title":"全球化思考:怎樣克服交流中的文化差異","tag":"201912","desc":""},"relativePath":"201912/20181018 Think global- How to overcome cultural communication challenges.md","filePath":"[post].md"}'),m={name:"201912/20181018 Think global- How to overcome cultural communication challenges.md"};function u(h,a,f,b,T,k){const t=s("Link");return p(),d("div",null,[a[21]||(a[21]=r('<h1 id="全球化思考-怎樣克服交流中的文化差異" tabindex="-1">全球化思考:怎樣克服交流中的文化差異 <a class="header-anchor" href="#全球化思考-怎樣克服交流中的文化差異" aria-label="Permalink to “全球化思考:怎樣克服交流中的文化差異”">​</a></h1><blockquote><p>這有一些建議幫助你的全球化開發團隊能夠更好地理解你們的討論並能參與其中。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/people_remote_teams_world.png?itok=_9DCHEel" alt=""></p><p>幾周前，我見證了兩位同事之間一次有趣的互動，他們分別是 Jason，我們的一位美國員工，和 Raj，一位來自印度的訪問工作人員。</p><p>Raj 在印度時，他一般會通過電話參加美國中部時間上午 9 點的每日立會，現在他到美國工作了，就可以和組員們坐在同一間會議室裏開會了。Jason 攔下了 Raj，説：“Raj 你要去哪？你不是一直和我們開電話會議嗎？你突然出現在會議室裏我還不太適應。” Raj 聽了説，“是這樣嗎？沒問題。”就回到自己工位前準備和以前一樣參加電話會議了。</p><p>我去找 Raj，問他為什麼不去參加每日立會，Raj 説 Jason 讓自己給組員們打電話參會，而與此同時，Jason 也在會議室等着 Raj 來參加立會。</p><p>到底是哪裏出的問題？Jason 明顯只是調侃 Raj 終於能來一起開會了，為什麼 Raj 沒能聽懂呢？</p><p>Jason 明顯是在開玩笑，但 Raj 把它當真了。這就是在兩人互相不瞭解對方文化語境時發生的一個典型誤會。</p><p>我經常會遇到有人在電子郵件的末尾寫“請復原”，最開始我很迷惑，“這有什麼需要我復原的內容？”後來我才搞懂，“請復原”其實是“請回復”的意思。</p>',9)),n("p",null,[a[1]||(a[1]=e("在 Ricardo Fernandez 的TED 演講“",-1)),l(t,{href:"https://www.youtube.com/watch?v=QIoAkFpN8wQ"},{default:o(()=>[...a[0]||(a[0]=[e("如何管理跨文化團隊",-1)])]),_:1}),a[2]||(a[2]=e("” 中，他提到了自己與一位南非同事發生的小故事。那位同事用一句“我一會給你打電話。”結束了兩人的 IM 會話，Ricardo 回到辦公室後就開始等這位同事的電話，十五分鐘後他忍不住主動給這位同事打了電話，問他:“你不是説要給我打電話嗎？”，這位同事答到:“是啊，我是説以後有機會給你打電話。”這時 Ricardo 才理解那位同事説的“一會”是“以後”的意思。",-1))]),a[22]||(a[22]=n("p",null,"現在是全球化時代，我們的同事很可能不跟我們面對面接觸，甚至不在同一座城市，來自不同的國家。越來越多的技術公司擁有全球化的工作場所，和來自世界各地的員工，他們有着不同的背景和經歷。這種多樣性使得技術公司能夠在這個快速發展的科技大環境下擁有更強的競爭力。",-1)),a[23]||(a[23]=n("p",null,"但是這種地域的多樣性也會給團隊帶來挑戰。管理和維持高性能的團隊發展對於同地協作的團隊來説就有着很大難度，對於有着多樣背景成員的全球化團隊來説，無疑更加困難。成員之間的交流會發生延遲，誤解時有發生，成員之間甚至會互相懷疑，這些都會影響着公司的成功。",-1)),n("p",null,[a[4]||(a[4]=e("到底是什麼因素讓全球化交流間發生誤解呢？我們可以參照 Erin Meyer 的書《",-1)),l(t,{href:"https://www.amazon.com/The-Culture-Map-Invisible-Boundaries/dp/1610392507"},{default:o(()=>[...a[3]||(a[3]=[e("文化地圖",-1)])]),_:1}),a[5]||(a[5]=e("》，她在書中將全球文化分為八個類型，其中美國文化被分為低語境文化，與之相對的，日本為高語境文化。",-1))]),a[24]||(a[24]=r('<p>看到這裏你可能會問，高、低語境文化到底是什麼意思？美國人從小就教育孩子們簡潔表達，“直言不諱”是他們的表達準則；另一邊，日本人從小學習在高效處理社交線索的同時進行交流，“察言觀色”是他們的交流習慣。</p><p>大部分亞洲國家的文化都屬於高語境文化。作為一個年輕的移民國家，美國毫不意外地擁有着低語境文化。移民來自於世界各地，擁有着不同的文化背景，他們不得不選擇簡潔而直接的交流方式，這或許就是其擁有低語境文化的原因。</p><h3 id="從文化語境的角度與異國同事交流的三個步驟" tabindex="-1">從文化語境的角度與異國同事交流的三個步驟： <a class="header-anchor" href="#從文化語境的角度與異國同事交流的三個步驟" aria-label="Permalink to “從文化語境的角度與異國同事交流的三個步驟：”">​</a></h3><p>怎樣面臨跨文化交流中遇到的挑戰？比如説一位美國人與他的日本同事交流，他更應該注重日本同事的非語言線索，同樣的日本同事應當更關注美國人直接表達出的信息。如果你也面臨類似的挑戰，按照下面這三個步驟做，可以幫助你更有效地和異國同事交流，增進與他們的感情。</p><h4 id="認識到文化語境的差異" tabindex="-1">認識到文化語境的差異 <a class="header-anchor" href="#認識到文化語境的差異" aria-label="Permalink to “認識到文化語境的差異”">​</a></h4><p>跨文化交流的第一步是認識到文化差異，跨文化交流從認識其他文化開始。</p><h4 id="尊重文化語境的差異" tabindex="-1">尊重文化語境的差異 <a class="header-anchor" href="#尊重文化語境的差異" aria-label="Permalink to “尊重文化語境的差異”">​</a></h4><p>一旦你意識到了文化語境的差異會影響跨文化交流，你要做的就是尊重這些差異。在你遇到一種不同的交流方式時，學會接受差異，學會積極聽取他人意見。</p><h4 id="調和文化語境的差異" tabindex="-1">調和文化語境的差異 <a class="header-anchor" href="#調和文化語境的差異" aria-label="Permalink to “調和文化語境的差異”">​</a></h4><p>只是認識和尊重差異還遠遠不夠，你還需要學會如何調和這些差異。互相理解和換位思考可以增進差異的調和，你還要學着用它們去提高同事間的交流效率，推動生產力。</p><h3 id="五種促進不同文化語境間交流的方法" tabindex="-1">五種促進不同文化語境間交流的方法 <a class="header-anchor" href="#五種促進不同文化語境間交流的方法" aria-label="Permalink to “五種促進不同文化語境間交流的方法”">​</a></h3><p>為了加強組員們之間關係，這麼多年來我一直在收集各種各樣的方法和建議。這些方法幫助我解決了與外國組員間產生的很多交流問題，下面有其中一些例子：</p><h4 id="與外國組員交流時儘量使用視頻會議的形式" tabindex="-1">與外國組員交流時儘量使用視頻會議的形式 <a class="header-anchor" href="#與外國組員交流時儘量使用視頻會議的形式" aria-label="Permalink to “與外國組員交流時儘量使用視頻會議的形式”">​</a></h4><p>研究表明，交流中約 55% 的內容不是靠語言傳遞的。肢體語言傳達着一種十分微妙的信息，你可以根據它們理解對方的意思，而視頻會議中處於異地的組員們能夠看到對方的肢體語言。因此，組織遠程會議時我一般都會採用視頻會議的形式。</p><h4 id="確保每位成員都有機會分享他們的想法" tabindex="-1">確保每位成員都有機會分享他們的想法 <a class="header-anchor" href="#確保每位成員都有機會分享他們的想法" aria-label="Permalink to “確保每位成員都有機會分享他們的想法”">​</a></h4><p>我雖然喜歡開視頻會議，但不是每次都能開的成。如果視頻會議對你的團隊來説並不常用，大家可能要一些時間去適應，你需要積極鼓勵大家參與到其中，先從進行語音會議開始。</p><p>我們有一個外地的組員，每次都和我們進行語音會議，和我們提到她經常會有些想法想要分享，或者想做些貢獻，但是我們互相看不到，她不知道該怎樣開口。如果你一直在進行語音會議，注意要給組員們足夠的時間和機會分享他們的想法。</p><h4 id="互相學習" tabindex="-1">互相學習 <a class="header-anchor" href="#互相學習" aria-label="Permalink to “互相學習”">​</a></h4><p>通過你身邊一兩名外國朋友來學習他們的文化，你可以把從一位同事身上學到的應用於所有來自這個國家的同事。我有幾位南亞和南美的同事，他們幫助我理解他們的文化，而這些也使得我更加專業。</p><p>對編程人員來説，我建議請你全世界的同行們檢查你的代碼，這個過程能讓你觀察到其他文化中人們怎樣進行反饋、勸説他人，和最終進行技術決策。</p><h4 id="學會感同身受" tabindex="-1">學會感同身受 <a class="header-anchor" href="#學會感同身受" aria-label="Permalink to “學會感同身受”">​</a></h4><p>同理心是一段牢固關係的核心。你越能換位思考，就越容易獲得信任，來建立長久的關係。你可以在每次會議開始之前和大家閒聊幾句，這樣大家更容易處於一個放鬆的狀態，如果團隊中有很多外國人，要確保大家都能參與進來。</p><h4 id="和你的外國同事們單獨見面" tabindex="-1">和你的外國同事們單獨見面 <a class="header-anchor" href="#和你的外國同事們單獨見面" aria-label="Permalink to “和你的外國同事們單獨見面”">​</a></h4><p>保持長久關係最好的方法是和你的組員們單獨見面。如果你的公司可以報銷這些費用，那麼努力去和組員們見面吧。和一起工作了很長時間的組員們見面能夠使你們的關係更加堅固。我所在的公司就有着週期性交換員工的傳統，每隔一段時間，世界各地的員工就會來到美國工作，美國員工再到其他分部工作。</p><p>另一種聚齊組員們的機會是研討會。研討會創造的不僅是學習和培訓的機會，你還可以擠出一些時間和組員們培養感情。</p><p>在如今，全球化經濟不斷發展，擁有來自不同國家和地區的員工對維持一個公司的競爭力來説越來越重要。即使組員們來自世界各地，團隊中會出現一些交流問題，但擁有一支國際化的高績效團隊不是問題。如果你在工作中有什麼促進團隊交流的小竅門，請在評論中告訴我們吧。</p><hr>',27)),n("p",null,[a[7]||(a[7]=e("via: ",-1)),l(t,{href:"https://opensource.com/article/18/10/think-global-communication-challenges"},{default:o(()=>[...a[6]||(a[6]=[e("https://opensource.com/article/18/10/think-global-communication-challenges",-1)])]),_:1})]),n("p",null,[a[12]||(a[12]=e("作者：",-1)),l(t,{href:"https://opensource.com/users/avindrafernando"},{default:o(()=>[...a[8]||(a[8]=[e("Avindra Fernando",-1)])]),_:1}),a[13]||(a[13]=e(" 選題：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...a[9]||(a[9]=[e("lujun9972",-1)])]),_:1}),a[14]||(a[14]=e(" 譯者：",-1)),l(t,{href:"https://github.com/Valoniakim"},{default:o(()=>[...a[10]||(a[10]=[e("Valoniakim",-1)])]),_:1}),a[15]||(a[15]=e(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:o(()=>[...a[11]||(a[11]=[e("wxy",-1)])]),_:1})]),n("p",null,[a[18]||(a[18]=e("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[16]||(a[16]=[e("LCTT",-1)])]),_:1}),a[19]||(a[19]=e(" 原創編譯，",-1)),l(t,{href:"https://linux.cn/"},{default:o(()=>[...a[17]||(a[17]=[e("Linux中國",-1)])]),_:1}),a[20]||(a[20]=e(" 榮譽推出",-1))])])}const P=i(m,[["render",u]]);export{C as __pageData,P as default};
